import marshal
from flask import Flask, request
import binascii

app = Flask(__name__)

@app.route('/unmarshal')
def unmarshal_data():
    '''
    Ambil data yang sudah dimarshall dari permintaan dengan menggunakan 'data' sebagai kunci. 
Unmarshal data tersebut dengan mengonversinya dari hex ke bytes,
Kembalikan data yang telah diunmarshal.
    '''
    marshalled_hex_data = request.args.get('data')
    if marshalled_hex_data:
        try:
            marshalled_data = binascii.unhexlify(marshalled_hex_data)
            unmarshalled_data = marshal.loads(marshalled_data)
            return str(unmarshalled_data)
        except Exception as e:
            return f"Error unmarshalling data: {str(e)}"
    else:
        return "No data provided."

if __name__ == '__main__':
    app.run(debug=True)
